contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    // params: from address, target contract address caddress, dynamic tos array, value v
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        // require _tos length > 0 to match function's precondition space; otherwise transfer would revert by require
        require(_tos.length > 0);

        bool reverted;
        bool ret;
        // perform the call and capture whether it reverted
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false; // meaningless when reverted but set for use in assert
        }

        // General rule: if call did not revert, return value must be true (never false)
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

